      return;
    }
    this.saving = true;
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { name, from, to, cap }, {
          headers: { 'X-User': this.session.user() ?? '' },
