                || !TERMS.matcher(terms).matches() || contact.length() > CONTACT_MAX) {
            throw new PersonImportRefusedException();
        }
        return new Line(name, grade, terms.isEmpty() ? null : Integer.valueOf(terms),
                contact.isEmpty() ? null : contact);
    }
